// CONFIDENCE: MEDIUM. Accept only the current query handle, then notify each newly hit actor that implements the sequencer interface.
if (HitActorsQueryHandle != Handle)
{
    return;
}
for (const FOverlapResult& Result : Results)
{
    AActor* Actor = ResolveActorId(Result.ActorId);      // native 0x14407cf10
    if (Actor == nullptr)
    {
        continue;
    }
    const FActorId ActorId = MakeActorId(Actor);          // native 0x142ee3b30
    bool bAlreadyHit = false;
    AddHitActor(ActorId, bAlreadyHit);                     // native 0x14077ea60
    if (!bAlreadyHit && Actor->GetClass()->ImplementsInterface(UFortMusicSequencerInterface::StaticClass()))   // 0x142d6a820
    {
        NotifyHitActor(Actor);                             // native 0x142749ff0
    }
}
